/**
 * lib/modsync — NX Labs catalog ingestion (agent K2). Provider-agnostic types.
 *
 * A Provider turns one upstream API into NormalizedMod records; the runner
 * upserts them idempotently (GameMod + ModVersion). Providers are RESUMABLE:
 * `run()` processes a bounded slice and returns a new cursor, so the worker
 * can interleave providers and survive restarts.
 */

export type ModChannel = "release" | "beta" | "alpha" | "snapshot";

export interface NormalizedVersion {
  versionId: string;
  versionNumber: string;
  channel: ModChannel;
  gameVersions: string[];
  loaders: string[];
  fileName?: string | null;
  fileUrl?: string | null;
  fileBytes?: number | null;
  sha1?: string | null;
  sha256?: string | null;
  sha512?: string | null;
  downloads?: number | null;
  changelog?: string | null;
  dependencies?: unknown;
  publishedAt?: Date | null;
}

export interface NormalizedMod {
  gameFamily: string;
  source: string; // GameMod.source vocabulary (modrinth, hangar, factorio_portal, ficsit, ...)
  sourceId: string; // stable provider id — the dedupe key with (gameFamily, source)
  slugHint: string; // preferred slug; runner resolves collisions
  name: string;
  category: string; // Nxeon coarse category (Mods, Plugins, Modpacks, ...)
  description?: string | null;
  /** Raw long body + its format; sanitised into bodyHtml by the runner. */
  body?: string | null;
  bodyFormat?: "markdown" | "html" | "bbcode";
  url?: string | null;
  sourceUrl?: string | null;
  iconUrl?: string | null;
  galleryUrls?: string[];
  authorName?: string | null;
  authorAvatarUrl?: string | null;
  license?: string | null; // SPDX id or provider's license name
  licenseUrl?: string | null;
  downloads?: number | null;
  followers?: number | null;
  categories?: string[];
  tags?: string[];
  gameVersions?: string[];
  loaders?: string[];
  serverSide?: string | null;
  appliesToVariant?: string | null;
  paid?: boolean;
  upstreamUpdatedAt?: Date | null;
  versions?: NormalizedVersion[];
}

export interface SyncContext {
  /** Rate-limited, backoff-aware fetch bound to this provider (lib/modsync/http.ts). */
  http: import("./http").HttpClient;
  /** Cursor from the previous slice (null on a fresh run). */
  cursor: Record<string, unknown> | null;
  /** Budget for this slice. */
  maxMods: number;
  deadline: number; // epoch ms — stop starting new pages after this
  log: (msg: string) => void;
  /** Hand a batch to the runner for upserting. */
  emit: (mods: NormalizedMod[]) => Promise<void>;
  /** True if the operator paused/disabled the provider mid-run. */
  shouldStop: () => Promise<boolean>;
}

export interface SliceResult {
  /** New cursor to resume from; null when the full pass finished. */
  cursor: Record<string, unknown> | null;
  done: boolean;
}

export interface Provider {
  key: string;
  label: string;
  /** Games this provider can supply. */
  games: string[];
  /** Requests/min ceiling we self-impose (under the upstream's published limit). */
  ratePerMin: number;
  /** Default minutes between full passes. */
  intervalMinutes: number;
  /** Off by default pending owner/ToS action (e.g. uMod). */
  defaultEnabled: boolean;
  /** Human verdict summary mirrored from docs/MODS-SOURCES.md. */
  policy: "mirror-if-licensed" | "metadata-only";
  run(ctx: SyncContext): Promise<SliceResult>;
}
