/**
 * Polite HTTP for upstream mod APIs: identifying User-Agent, token-bucket
 * pacing, exponential backoff with jitter, Retry-After honouring, and
 * ETag / If-Modified-Since conditional requests. No upstream is ever hit
 * faster than its provider's `ratePerMin`.
 */

export const MODSYNC_UA = "NxeonModSync/1.0 (+https://nxeon.cloud; mods@nxeon.cloud)";

export interface HttpOptions {
  ratePerMin: number;
  maxRetries?: number;
  headers?: Record<string, string>;
  fetchImpl?: typeof fetch;
  sleep?: (ms: number) => Promise<void>;
  now?: () => number;
}

export interface CondOpts {
  etag?: string | null;
  lastModified?: string | null;
}

export class HttpError extends Error {
  constructor(public status: number, public url: string, msg?: string) {
    super(msg ?? `HTTP ${status} for ${url}`);
  }
}

export class HttpClient {
  private nextSlot = 0;
  private readonly gap: number;
  private readonly fetchImpl: typeof fetch;
  private readonly sleep: (ms: number) => Promise<void>;
  private readonly now: () => number;
  requests = 0;
  retries = 0;

  constructor(private opts: HttpOptions) {
    this.gap = Math.ceil(60_000 / Math.max(1, opts.ratePerMin));
    this.fetchImpl = opts.fetchImpl ?? fetch;
    this.sleep = opts.sleep ?? ((ms) => new Promise((r) => setTimeout(r, ms)));
    this.now = opts.now ?? Date.now;
  }

  private async pace() {
    const t = this.now();
    const wait = Math.max(0, this.nextSlot - t);
    this.nextSlot = Math.max(t, this.nextSlot) + this.gap;
    if (wait > 0) await this.sleep(wait);
  }

  /** Backoff delay for attempt n (0-based): 1s,2s,4s,... capped 60s, +jitter. */
  static backoffMs(attempt: number, retryAfter?: string | null, rnd = Math.random): number {
    if (retryAfter) {
      const s = Number(retryAfter);
      if (Number.isFinite(s) && s >= 0) return Math.min(120_000, s * 1000 + 250);
      const d = Date.parse(retryAfter);
      if (Number.isFinite(d)) return Math.min(120_000, Math.max(0, d - Date.now()) + 250);
    }
    return Math.min(60_000, 1000 * 2 ** attempt) + Math.floor(rnd() * 400);
  }

  /** Raw request with pacing + retry on 429/5xx/network errors. 304 is returned as-is. */
  async request(url: string, init: RequestInit & { cond?: CondOpts } = {}): Promise<Response> {
    const maxRetries = this.opts.maxRetries ?? 5;
    const headers: Record<string, string> = {
      "User-Agent": MODSYNC_UA,
      Accept: "application/json",
      ...(this.opts.headers ?? {}),
      ...((init.headers as Record<string, string>) ?? {}),
    };
    if (init.cond?.etag) headers["If-None-Match"] = init.cond.etag;
    if (init.cond?.lastModified) headers["If-Modified-Since"] = init.cond.lastModified;
    let lastErr: unknown;
    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      await this.pace();
      this.requests++;
      try {
        const res = await this.fetchImpl(url, { ...init, headers, signal: init.signal ?? AbortSignal.timeout(60_000) });
        if (res.status === 429 || res.status >= 500) {
          lastErr = new HttpError(res.status, url);
          if (attempt === maxRetries) throw lastErr;
          this.retries++;
          const ra = res.headers.get("retry-after");
          try { await res.arrayBuffer(); } catch {}
          await this.sleep(HttpClient.backoffMs(attempt, ra));
          continue;
        }
        return res;
      } catch (e) {
        if (e instanceof HttpError) throw e;
        lastErr = e;
        if (attempt === maxRetries) throw e;
        this.retries++;
        await this.sleep(HttpClient.backoffMs(attempt));
      }
    }
