/**
 * Local mirror of mod FILES — content-addressed, license-gated, budgeted.
 *
 * Layout:  <NXLABS_MIRROR_DIR>/files/<sha256[0:2]>/<sha256>     (immutable blobs)
 *          <NXLABS_MIRROR_DIR>/img/<aa>/<sha256>.webp           (cached images)
 *          <NXLABS_MIRROR_DIR>/tmp/                             (in-flight downloads)
 * Provider/game/mod/version metadata lives in Postgres (ModVersion), NOT in the
 * path: the path is only the hash, so identical files dedupe across versions
 * and a rename upstream never orphans anything.
 *
 * Policy (docs/MODS-SOURCES.md): a file is mirrored only if its GameMod is
 * `redistributable` (open SPDX license) AND the provider is mirror-eligible.
 * Everything else is SKIPPED (metadata + link-through).
 *
 * Fast path for installers: `resolveLocal(modVersion)` -> absolute path | null.
 */
import { createHash } from "node:crypto";
import { createReadStream, createWriteStream } from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import { Transform } from "node:stream";
import { db } from "@/lib/db";
import type { HttpClient } from "./http";
import { filesRoot, mirrorMaxBytes, mirrorMaxFileBytes, tmpRoot } from "./config";

const SHA256_RE = /^[a-f0-9]{64}$/;

export function blobRel(sha256: string): string {
  if (!SHA256_RE.test(sha256)) throw new Error("bad sha256");
  return path.posix.join("files", sha256.slice(0, 2), sha256);
}
export function blobAbs(rel: string): string {
  const root = path.resolve(path.dirname(filesRoot()));
  const abs = path.resolve(root, rel);
  if (!abs.startsWith(root + path.sep)) throw new Error("path escapes mirror root");
  return abs;
}

type VersionLike = { id: string; mirrorState?: string; mirrorPath?: string | null; mirrorBytes?: number | null };

/**
 * Absolute path of the locally mirrored file for this version, or null (not
 * mirrored / evicted / file missing or truncated). Touches lastAccessedAt so
 * popular files survive eviction. O(1): stat only; use `verifyMirror` for hashes.
 */
export async function resolveLocal(mv: VersionLike | string): Promise<string | null> {
  const row =
    typeof mv === "string"
      ? await db.modVersion.findUnique({ where: { id: mv }, select: { id: true, mirrorState: true, mirrorPath: true, mirrorBytes: true } })
      : mv.mirrorState !== undefined
        ? mv
        : await db.modVersion.findUnique({ where: { id: mv.id }, select: { id: true, mirrorState: true, mirrorPath: true, mirrorBytes: true } });
  if (!row || row.mirrorState !== "OK" || !row.mirrorPath) return null;
  let abs: string;
  try {
    abs = blobAbs(row.mirrorPath);
    const st = await fs.stat(abs);
    if (row.mirrorBytes != null && st.size !== row.mirrorBytes) return null;
  } catch {
    return null;
  }
  void db.modVersion
    .update({ where: { id: row.id }, data: { lastAccessedAt: new Date(), accessCount: { increment: 1 } } })
    .catch(() => {});
  return abs;
}

export type MirrorOutcome = "OK" | "SKIPPED" | "FAILED" | "ALREADY";

/** Download one version into the mirror (hash-verified against provider digests). */
export async function mirrorVersion(http: HttpClient, versionRowId: string): Promise<{ outcome: MirrorOutcome; reason?: string }> {
  const v = await db.modVersion.findUnique({ where: { id: versionRowId }, include: { gameMod: true } });
  if (!v) return { outcome: "FAILED", reason: "version not found" };
  if (v.mirrorState === "OK" && v.mirrorPath && (await resolveLocalQuiet(v.mirrorPath, v.mirrorBytes))) return { outcome: "ALREADY" };
  const skip = async (reason: string) => {
    await db.modVersion.update({ where: { id: v.id }, data: { mirrorState: "SKIPPED", mirrorError: reason } });
    return { outcome: "SKIPPED" as const, reason };
  };
  if (!v.gameMod.redistributable) return skip(`license "${v.gameMod.license ?? "none"}" does not permit redistribution`);
  if (!v.fileUrl || !/^https:\/\//i.test(v.fileUrl)) return skip("no direct https file URL");
  if (v.fileBytes != null && v.fileBytes > mirrorMaxFileBytes()) return skip(`file ${v.fileBytes}B exceeds per-file cap`);
  if (v.gameMod.paid) return skip("paid resource");

  await fs.mkdir(tmpRoot(), { recursive: true });
  const tmp = path.join(tmpRoot(), `${v.id}.${process.pid}.part`);
  try {
    const res = await http.request(v.fileUrl, { headers: { Accept: "*/*" } });
    if (!res.ok || !res.body) throw new Error(`HTTP ${res.status}`);
    const declared = Number(res.headers.get("content-length") ?? 0);
    const cap = mirrorMaxFileBytes();
    if (declared > cap) return skip(`file ${declared}B exceeds per-file cap`);
    const sha256 = createHash("sha256");
    const sha1 = createHash("sha1");
    const sha512 = createHash("sha512");
    let bytes = 0;
    const meter = new Transform({
      transform(chunk: Buffer, _enc, cb) {
        bytes += chunk.length;
        if (bytes > cap) return cb(new Error("exceeds per-file cap while streaming"));
        sha256.update(chunk); sha1.update(chunk); sha512.update(chunk);
        cb(null, chunk);
      },
    });
    await pipeline(Readable.fromWeb(res.body as never), meter, createWriteStream(tmp));
    const d256 = sha256.digest("hex");
    if (v.sha1 && v.sha1.toLowerCase() !== sha1.digest("hex")) throw new Error("sha1 mismatch vs provider digest");
    if (v.sha512 && v.sha512.toLowerCase() !== sha512.digest("hex")) throw new Error("sha512 mismatch vs provider digest");
    if (v.sha256 && v.sha256.toLowerCase() !== d256) throw new Error("sha256 mismatch vs provider digest");

    await ensureRoom(bytes, v.id);
    const rel = blobRel(d256);
    const abs = blobAbs(rel);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    try {
      await fs.access(abs);
      await fs.rm(tmp, { force: true }); // identical blob already stored (dedupe)
    } catch {
      await fs.rename(tmp, abs);
    }
    await db.modVersion.update({
      where: { id: v.id },
      data: { mirrorState: "OK", mirrorPath: rel, mirrorSha256: d256, mirrorBytes: bytes, mirrorError: null, mirroredAt: new Date(), lastAccessedAt: new Date(), sha256: v.sha256 ?? d256 },
    });
    return { outcome: "OK" };
  } catch (e) {
    await fs.rm(tmp, { force: true }).catch(() => {});
    const reason = e instanceof Error ? e.message : String(e);
    await db.modVersion.update({ where: { id: v.id }, data: { mirrorState: "FAILED", mirrorError: reason.slice(0, 500) } }).catch(() => {});
    return { outcome: "FAILED", reason };
  }
}

async function resolveLocalQuiet(rel: string, bytes?: number | null): Promise<boolean> {
  try {
    const st = await fs.stat(blobAbs(rel));
    return bytes == null || st.size === bytes;
  } catch {
    return false;
  }
}

/** Sum of distinct blob bytes currently held (dedupe-aware). */
export async function mirrorUsage(): Promise<{ files: number; bytes: number; budget: number }> {
