  const tmp = path.join(tmpRoot(), `${v.id}.${process.pid}.part`);
  try {
    const res = await http.request(v.fileUrl, { headers: { Accept: "*/*" } });
    if (!res.ok || !res.body) throw new Error(`HTTP ${res.status}`);
    const declared = Number(res.headers.get("content-length") ?? 0);
    const cap = mirrorMaxFileBytes();
    if (declared > cap) return skip(`file ${declared}B exceeds per-file cap`);
    const sha256 = createHash("sha256");
    const sha1 = createHash("sha1");
    const sha512 = createHash("sha512");
    let bytes = 0;
    const meter = new Transform({
      transform(chunk: Buffer, _enc, cb) {
        bytes += chunk.length;
        if (bytes > cap) return cb(new Error("exceeds per-file cap while streaming"));
        sha256.update(chunk); sha1.update(chunk); sha512.update(chunk);
        cb(null, chunk);
      },
    });
    await pipeline(Readable.fromWeb(res.body as never), meter, createWriteStream(tmp));
    const d256 = sha256.digest("hex");
    if (v.sha1 && v.sha1.toLowerCase() !== sha1.digest("hex")) throw new Error("sha1 mismatch vs provider digest");
    if (v.sha512 && v.sha512.toLowerCase() !== sha512.digest("hex")) throw new Error("sha512 mismatch vs provider digest");
    if (v.sha256 && v.sha256.toLowerCase() !== d256) throw new Error("sha256 mismatch vs provider digest");

    await ensureRoom(bytes, v.id);
    const rel = blobRel(d256);
    const abs = blobAbs(rel);
    await fs.mkdir(path.dirname(abs), { recursive: true });
    try {
      await fs.access(abs);
      await fs.rm(tmp, { force: true }); // identical blob already stored (dedupe)
    } catch {
      await fs.rename(tmp, abs);
    }
    await db.modVersion.update({
      where: { id: v.id },
      data: { mirrorState: "OK", mirrorPath: rel, mirrorSha256: d256, mirrorBytes: bytes, mirrorError: null, mirroredAt: new Date(), lastAccessedAt: new Date(), sha256: v.sha256 ?? d256 },
    });
    return { outcome: "OK" };
  } catch (e) {
    await fs.rm(tmp, { force: true }).catch(() => {});
    const reason = e instanceof Error ? e.message : String(e);
    await db.modVersion.update({ where: { id: v.id }, data: { mirrorState: "FAILED", mirrorError: reason.slice(0, 500) } }).catch(() => {});
    return { outcome: "FAILED", reason };
  }
}

