}

/** Re-hash stored blobs (oldest-verified first is overkill here: caller passes a limit). */
export async function verifyMirror(limit = 50): Promise<{ checked: number; corrupt: number }> {
  const rows = await db.modVersion.findMany({ where: { mirrorState: "OK" }, take: limit, orderBy: { mirroredAt: "asc" }, select: { id: true, mirrorPath: true, mirrorSha256: true } });
