/**
 * Idempotent persistence of NormalizedMod -> GameMod + ModVersion.
 * Dedupe key: (gameFamily, source, sourceId); falls back to the existing
 * @@unique([gameFamily, slug]) with collision-suffixing, same convention as the
 * legacy scripts/import-*.ts so re-ingesting rows those scripts created
 * UPDATES them instead of duplicating.
 */
import { db } from "@/lib/db";
import { renderModBody } from "@/lib/mod-markdown";
import type { HttpClient } from "./http";
import { cacheImage, ICON_SIZE, SHOT_SIZE } from "./images";
import { isRedistributable, normalizeLicense } from "./license";
import type { NormalizedMod } from "./types";

export function slugify(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 80) || "mod";
}

const GALLERY_CAP = 8;
const VERSION_CAP = 25; // newest N builds per mod: enough for the compat matrix, bounded rows

export interface UpsertOpts {
  http?: HttpClient; // required for image caching
  cacheImages?: boolean;
  /** Pre-fetched set of slugs in use for the family (perf for big batches). */
}

export async function upsertMod(m: NormalizedMod, opts: UpsertOpts = {}): Promise<"created" | "updated"> {
  const existing = await db.gameMod.findFirst({
    where: { gameFamily: m.gameFamily, source: m.source, sourceId: m.sourceId },
    select: { id: true, slug: true, iconUrl: true, iconKey: true, galleryUrls: true, galleryKeys: true },
  });
  const license = normalizeLicense(m.license);
  const gallery = (m.galleryUrls ?? []).filter((u) => /^https:\/\//i.test(u)).slice(0, GALLERY_CAP);

  let iconKey = existing?.iconUrl === (m.iconUrl ?? null) ? existing?.iconKey ?? null : null;
  let galleryKeys = existing && JSON.stringify(existing.galleryUrls) === JSON.stringify(gallery) ? existing.galleryKeys : [];
  if (opts.cacheImages && opts.http) {
    if (m.iconUrl && !iconKey) iconKey = await cacheImage(opts.http, m.iconUrl, ICON_SIZE);
    if (gallery.length && galleryKeys.length !== gallery.length) {
      const keys: string[] = [];
      for (const g of gallery.slice(0, 4)) {
        const k = await cacheImage(opts.http, g, SHOT_SIZE);
        if (k) keys.push(k);
      }
      galleryKeys = keys;
    }
  }

  const body = m.body?.trim() ? m.body : null;
  const bodyHtml = body
    ? renderModBody(body, m.bodyFormat === "markdown" ? "modrinth" : "other", 12000).html
    : null;

  const versions = m.versions ?? [];
  const latest = versions[0];
  const data = {
    name: m.name.slice(0, 200),
    category: m.category,
    description: m.description?.slice(0, 600) || null,
    longDescription: body,
    bodyHtml,
    url: m.url ?? null,
    sourceUrl: m.sourceUrl ?? null,
    iconUrl: m.iconUrl ?? null,
    iconKey,
    galleryUrls: gallery,
    galleryKeys,
    authorName: m.authorName ?? null,
    authorAvatarUrl: m.authorAvatarUrl ?? null,
    license,
    licenseUrl: m.licenseUrl ?? null,
    redistributable: isRedistributable(license),
    downloads: m.downloads ?? null,
    followers: m.followers ?? null,
    categories: m.categories ?? [],
    tags: m.tags ?? [],
    gameVersions: m.gameVersions ?? [],
    loaders: m.loaders ?? [],
    serverSide: m.serverSide ?? null,
    appliesToVariant: m.appliesToVariant ?? null,
    paid: m.paid ?? false,
    latestVersion: latest?.versionNumber ?? null,
    upstreamUpdatedAt: m.upstreamUpdatedAt ?? null,
    source: m.source,
    sourceId: m.sourceId,
    active: true,
    upstreamOk: true,
    upstreamNote: null,
    verifiedAt: new Date(),
    syncedAt: new Date(),
  };

  let id: string;
  let result: "created" | "updated";
  if (existing) {
    await db.gameMod.update({ where: { id: existing.id }, data });
    id = existing.id;
    result = "updated";
  } else {
    let slug = m.slugHint || slugify(m.name);
    for (let i = 2; await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: m.gameFamily, slug } }, select: { id: true } }); i++) {
      slug = `${m.slugHint || slugify(m.name)}-${i}`;
      if (i > 50) throw new Error(`slug exhaustion for ${m.name}`);
    }
    const row = await db.gameMod.create({ data: { gameFamily: m.gameFamily, slug, ...data }, select: { id: true } });
    id = row.id;
    result = "created";
  }

  for (const v of versions.slice(0, VERSION_CAP)) {
    const vd = {
      versionNumber: v.versionNumber.slice(0, 120),
      channel: v.channel,
      gameVersions: v.gameVersions,
      loaders: v.loaders,
      fileName: v.fileName ?? null,
      fileUrl: v.fileUrl ?? null,
      fileBytes: v.fileBytes ?? null,
      sha1: v.sha1 ?? null,
      sha256: v.sha256 ?? null,
      sha512: v.sha512 ?? null,
      downloads: v.downloads ?? null,
      changelog: v.changelog?.slice(0, 8000) || null,
      dependencies: (v.dependencies ?? undefined) as never,
      publishedAt: v.publishedAt ?? null,
    };
    await db.modVersion.upsert({
      where: { gameModId_versionId: { gameModId: id, versionId: v.versionId } },
      update: vd,
      create: { gameModId: id, versionId: v.versionId, ...vd },
    });
  }
  return result;
}
