/**
 * Hangar (PaperMC plugin repository) — game: minecraft. Public REST API
 * https://hangar.papermc.io/api-docs. Plugin license is declared per project
 * (`settings.license`); file stored only when it maps to an open SPDX family.
 * One list call returns 25 projects incl. their README + supported versions;
 * versions need one extra call per project (limited to the popular slice).
 */
import type { NormalizedMod, NormalizedVersion, Provider, SliceResult, SyncContext } from "../types";

const API = "https://hangar.papermc.io/api/v1";
const PAGE = 25;

export interface HgProject {
  id: string | number; name: string; namespace: { owner: string; slug: string }; description?: string;
  category?: string; lastUpdated?: string; mainPageContent?: string; avatarUrl?: string | null; memberNames?: string[];
  stats?: { downloads?: number; stars?: number; watchers?: number };
  settings?: { license?: { name?: string; url?: string | null; type?: string | null }; keywords?: string[]; tags?: string[]; links?: { links?: { name: string; url: string }[] }[] };
  supportedPlatforms?: Record<string, string[]>;
}
export interface HgVersion {
  id: string | number; name: string; createdAt: string; channel?: { name?: string };
  description?: string; stats?: { totalDownloads?: number };
  downloads?: Record<string, { fileInfo?: { name: string; sizeBytes: number; sha256Hash: string } | null; externalUrl?: string | null; downloadUrl?: string | null }>;
  platformDependencies?: Record<string, string[]>;
  pluginDependencies?: Record<string, { name: string; required: boolean }[]>;
}

export function parseHangarVersion(v: HgVersion): NormalizedVersion {
  const plats = Object.keys(v.downloads ?? {});
  const primary = (v.downloads ?? {})["PAPER"] ?? (v.downloads ?? {})[plats[0]];
  const ch = (v.channel?.name ?? "release").toLowerCase();
  const gv = [...new Set(Object.values(v.platformDependencies ?? {}).flat())];
  return {
    versionId: String(v.id),
    versionNumber: v.name,
    channel: ch.includes("snapshot") ? "snapshot" : ch.includes("beta") ? "beta" : ch.includes("alpha") ? "alpha" : "release",
    gameVersions: gv,
    loaders: plats.map((p) => p.toLowerCase()),
    fileName: primary?.fileInfo?.name ?? null,
    // externalUrl = hosted elsewhere (link-through only); downloadUrl = Hangar CDN.
    fileUrl: primary?.downloadUrl ?? null,
    fileBytes: primary?.fileInfo?.sizeBytes ?? null,
    sha256: primary?.fileInfo?.sha256Hash ?? null,
    downloads: v.stats?.totalDownloads ?? null,
    changelog: v.description || null,
    dependencies: v.pluginDependencies ?? {},
    publishedAt: v.createdAt ? new Date(v.createdAt) : null,
  };
}

export function parseHangarProject(p: HgProject, versions: HgVersion[]): NormalizedMod {
  const ns = p.namespace;
  const lic = p.settings?.license;
  const links = (p.settings?.links ?? []).flatMap((l) => l.links ?? []);
  const src = links.find((l) => /^source/i.test(l.name))?.url ?? null;
  const supported = p.supportedPlatforms ?? {};
  return {
    gameFamily: "minecraft",
    source: "hangar",
    sourceId: `${ns.owner}/${ns.slug}`,
    slugHint: `${ns.slug.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "")}`,
    name: p.name,
    category: "Plugins",
    description: p.description || null,
    body: p.mainPageContent || null,
    bodyFormat: "markdown",
    url: `https://hangar.papermc.io/${ns.owner}/${ns.slug}`,
    sourceUrl: src,
    iconUrl: p.avatarUrl ?? null,
    authorName: ns.owner,
    license: lic?.type && lic.type !== "Other" ? lic.type : lic?.name || null,
    licenseUrl: lic?.url ?? null,
    downloads: p.stats?.downloads ?? null,
    followers: p.stats?.stars ?? null,
    categories: p.category ? [p.category] : [],
    tags: [...(p.settings?.keywords ?? []), ...(p.settings?.tags ?? []).map((t) => t.toLowerCase())],
    gameVersions: [...new Set(Object.values(supported).flat())],
