        if (!body.hits.length) break;
        const ids = body.hits.map((h) => h.project_id);
        const projects = await ctx.http.json<MrProject[]>(`${API}/projects?ids=${encodeURIComponent(JSON.stringify(ids))}`);
        const verIds = projects.flatMap((p) => (p.versions ?? []).slice(-VERSIONS_PER_MOD));
        const versions: MrVersion[] = [];
        for (let i = 0; i < verIds.length; i += 250) {
          versions.push(...(await ctx.http.json<MrVersion[]>(`${API}/versions?ids=${encodeURIComponent(JSON.stringify(verIds.slice(i, i + 250)))}`)));
        }
        const byProject = new Map<string, MrVersion[]>();
        for (const v of versions) byProject.set(v.project_id, [...(byProject.get(v.project_id) ?? []), v]);
        const authorOf = new Map(body.hits.map((h) => [h.project_id, h.author ?? null]));
        await ctx.emit(projects.map((p) => parseModrinthProject(p, authorOf.get(p.id) ?? null, byProject.get(p.id) ?? [])));
        produced += projects.length;
        offset += PAGE;
        ctx.log(`modrinth ${pt} offset=${offset}/${Math.min(body.total_hits, 10000)}`);
        // Meilisearch hard cap: offset+limit <= 10000.
        if (offset >= body.total_hits || offset + PAGE > 10000) break;
        // "recent" mode: a few pages of newest-updated is enough to pick up changes.
        if (ctx.mode === "recent" && offset >= PAGE * 5) break;
      }
      ti++;
      offset = 0;
    }
    return { cursor: null, done: true };
  },
};
