export function parseHangarVersion(v: HgVersion): NormalizedVersion {
  const plats = Object.keys(v.downloads ?? {});
  const primary = (v.downloads ?? {})["PAPER"] ?? (v.downloads ?? {})[plats[0]];
  const ch = (v.channel?.name ?? "release").toLowerCase();
  const gv = [...new Set(Object.values(v.platformDependencies ?? {}).flat())];
  return {
    versionId: String(v.id),
    versionNumber: v.name,
    channel: ch.includes("snapshot") ? "snapshot" : ch.includes("beta") ? "beta" : ch.includes("alpha") ? "alpha" : "release",
