    iconUrl: m.logo || null,
    authorName: m.authors?.[0]?.user?.username ?? null,
    downloads: m.downloads ?? null,
    gameVersions: best?.game_version ? [best.game_version] : [],
    loaders: [],
    serverSide: "required",
    upstreamUpdatedAt: m.last_version_date ? new Date(m.last_version_date) : null,
    versions,
  };
