export const ficsit: Provider = {
  key: "ficsit",
  label: "ficsit.app (Satisfactory)",
  games: ["satisfactory"],
  ratePerMin: 30,
  intervalMinutes: 24 * 60,
  defaultEnabled: true,
  policy: "metadata-only",
  async run(ctx: SyncContext): Promise<SliceResult> {
    let offset = Number(ctx.cursor?.offset ?? 0);
    const minDl = Number(process.env.MODSYNC_FICSIT_MIN_DOWNLOADS ?? 1000);
    let produced = 0;
    while (true) {
      if (produced >= ctx.maxMods || Date.now() > ctx.deadline || (await ctx.shouldStop())) return { cursor: { offset }, done: false };
      const query = `{ getMods(filter: { limit: ${PAGE}, offset: ${offset}, order_by: ${ctx.mode === "recent" ? "last_version_date" : "downloads"}, order: desc }) { count mods { name mod_reference short_description full_description logo downloads hidden last_version_date source_url authors { user { username } } latestVersions { release { ${VER} } beta { ${VER} } alpha { ${VER} } } } } }`;
