/**
 * Worker hook for NX Labs catalog ingestion (lib/modsync). One bounded slice of
 * at most one provider per call; the worker loop calls it every 5 minutes. All
 * state is in Postgres (ModSyncProvider.cursor), so restarts resume mid-pass.
 */
import { nextDueProvider, runProviderSlice } from "../lib/modsync/runner";

let busy = false;

export async function modsyncTick(): Promise<void> {
  if (process.env.MODSYNC_DISABLED === "1" || busy) return;
  busy = true;
  try {
    const key = await nextDueProvider();
    if (!key) return;
    const stats = await runProviderSlice(key, { budgetMs: 6 * 60_000, maxMods: 1500 });
    console.log(`[modsync] ${key}: seen=${stats.seen} created=${stats.created} updated=${stats.updated} failed=${stats.failed} mirrored=${stats.mirrored} done=${stats.done}`);
  } catch (e) {
    console.error("[modsync] tick error", e instanceof Error ? e.message : e);
  } finally {
    busy = false;
  }
}
