import fs from "node:fs/promises";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, StatCard, fmtBytes, timeAgo } from "@/components/ui/primitives";
import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { PROVIDERS, LEGACY_SOURCES } from "@/lib/modsync/registry";
import { ensureProviderRows } from "@/lib/modsync/runner";
import { mirrorUsage } from "@/lib/modsync/mirror";
import { mirrorDir } from "@/lib/modsync/config";
