export const dynamic = "force-dynamic";

type Cov = { gameFamily: string; n: bigint; icon: bigint; descr: bigint; ver: bigint; lic: bigint; shots: bigint; mirrored: bigint };

const statusTone = (s: string | null | undefined): "green" | "red" | "amber" | "brand" =>
  s === "ok" ? "green" : s === "error" ? "red" : s === "partial" || s === "running" ? "amber" : "brand";

/** NX Labs ingestion control room: provider status, mirror storage, per-game coverage. */
export default async function AdminNxLabsPage() {
  await requireArea("billing");
  await ensureProviderRows();

  const [rows, runs, usage, cov, legacy, imgs] = await Promise.all([
    db.modSyncProvider.findMany(),
    db.modSyncRun.findMany({ orderBy: { startedAt: "desc" }, take: 15 }),
    mirrorUsage(),
    db.$queryRaw<Cov[]>`
      select m."gameFamily", count(*)::bigint n,
        count(*) filter (where m."iconUrl" is not null)::bigint icon,
        count(*) filter (where coalesce(m.description,'')<>'')::bigint descr,
        count(*) filter (where cardinality(m."gameVersions")>0)::bigint ver,
        count(*) filter (where m.license is not null)::bigint lic,
        count(*) filter (where cardinality(m."galleryUrls")>0)::bigint shots,
        (select count(distinct v."gameModId") from "ModVersion" v join "GameMod" g on g.id=v."gameModId" where g."gameFamily"=m."gameFamily" and v."mirrorState"='OK')::bigint mirrored
      from "GameMod" m where m.active and m."upstreamOk" group by 1 order by 2 desc`,
    db.$queryRaw<{ source: string; n: bigint; last: Date | null }[]>`select source, count(*)::bigint n, max("verifiedAt") "last" from "GameMod" group by 1`,
    db.gameMod.count({ where: { iconKey: { not: null } } }),
  ]);
  const byKey = new Map(rows.map((r) => [r.key, r]));
  const srcCount = new Map(legacy.map((l) => [l.source, l]));
  let free: number | null = null;
  try {
    const st = await fs.statfs(mirrorDir());
    free = Number(st.bavail) * Number(st.bsize);
  } catch {}
  const total = cov.reduce((a, c) => a + Number(c.n), 0);
  const pct = (a: bigint, n: bigint) => (Number(n) ? `${Math.round((Number(a) / Number(n)) * 100)}%` : "—");

  return (
    <div>
      <PageHeader title="NX Labs ingestion" sub="Provider sync status, local mod mirror, and per-game catalog coverage. The worker runs the crawls; these controls only change its schedule.">
        <Badge tone="brand">{total.toLocaleString()} live mods</Badge>
      </PageHeader>

      <div className="mb-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
        <StatCard label="Mirror used" value={fmtBytes(usage.bytes)} delta={`of ${fmtBytes(usage.budget)} budget`} />
        <StatCard label="Mirrored files" value={usage.files.toLocaleString()} />
        <StatCard label="Cached images" value={imgs.toLocaleString()} />
        <StatCard label="Mirror disk free" value={free == null ? "n/a" : fmtBytes(free)} delta={mirrorDir()} />
      </div>

      <h2 className="mb-2 text-lg font-semibold">Providers</h2>
      <div className="mb-8 space-y-2">
        {PROVIDERS.map((p) => {
          const r = byKey.get(p.key);
          const s = (r?.lastStats ?? {}) as Record<string, number | string>;
          return (
            <div key={p.key} className="card">
              <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2 font-medium">
                    {p.label}
                    <Badge tone={statusTone(r?.lastStatus)}>{r?.lastStatus ?? "never run"}</Badge>
                    {r?.paused && <Badge tone="amber">paused</Badge>}
                    {r && !r.enabled && <Badge tone="red">disabled</Badge>}
                    <Badge tone="brand">{p.policy === "mirror-if-licensed" ? "mirror if licensed" : "metadata only"}</Badge>
                  </div>
                  <div className="mt-1 text-xs text-slate-500">
                    games: {p.games.join(", ")} · {srcCount.get(p.key === "factorio" ? "factorio_portal" : p.key)?.n.toString() ?? "0"} rows ·
                    last run {r?.lastRunAt ? timeAgo(r.lastRunAt) : "never"} · next {r?.nextRunAt ? (r.nextRunAt.getTime() < Date.now() ? "due" : timeAgo(new Date(2 * Date.now() - r.nextRunAt.getTime())).replace(" ago", "")) : "—"} ·
                    mode {String(s.mode ?? "—")} · seen {String(s.seen ?? 0)} / new {String(s.created ?? 0)} / upd {String(s.updated ?? 0)} / failed {String(s.failed ?? 0)} ·
                    mirrored {String(s.mirrored ?? 0)} · {String(s.requests ?? 0)} req ({String(s.retries ?? 0)} retried)
                    {r?.cursor ? " · resumable cursor saved" : ""}
                  </div>
                  {r?.lastError && <div className="mt-1 break-words text-xs text-red-400">{r.lastError}</div>}
                </div>
                {r && <NxLabsSyncControls providerKey={p.key} paused={r.paused} enabled={r.enabled} />}
              </div>
            </div>
          );
        })}
      </div>

      <h2 className="mb-2 text-lg font-semibold">Legacy importers (weekly timer, read-only here)</h2>
      <div className="card mb-8 overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead className="text-xs text-slate-500"><tr><th className="py-1">Source</th><th>Rows</th><th>Last verified</th><th>Policy</th></tr></thead>
          <tbody>
            {LEGACY_SOURCES.map((l) => {
              const c = srcCount.get(l.source);
              return (
                <tr key={l.source} className="border-t border-white/5">
                  <td className="py-1">{l.label}</td>
                  <td>{c ? Number(c.n).toLocaleString() : 0}</td>
                  <td>{c?.last ? timeAgo(c.last) : "never"}</td>
                  <td className="text-slate-400">{l.verdict}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <h2 className="mb-2 text-lg font-semibold">Coverage by game</h2>
      <div className="card mb-8 overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead className="text-xs text-slate-500">
            <tr><th className="py-1">Game</th><th>Mods</th><th>Icon</th><th>Description</th><th>Versions</th><th>License</th><th>Screenshots</th><th>Mirrored mods</th></tr>
          </thead>
          <tbody>
            {cov.map((c) => (
              <tr key={c.gameFamily} className="border-t border-white/5">
                <td className="py-1">{GAME_DISPLAY[c.gameFamily as GameFamily]?.name ?? c.gameFamily}</td>
                <td>{Number(c.n).toLocaleString()}</td>
                <td>{pct(c.icon, c.n)}</td><td>{pct(c.descr, c.n)}</td><td>{pct(c.ver, c.n)}</td><td>{pct(c.lic, c.n)}</td><td>{pct(c.shots, c.n)}</td>
                <td>{Number(c.mirrored).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <h2 className="mb-2 text-lg font-semibold">Recent runs</h2>
      <div className="card overflow-x-auto">
        <table className="w-full text-left text-sm">
          <thead className="text-xs text-slate-500"><tr><th className="py-1">Provider</th><th>Started</th><th>Status</th><th>Result</th></tr></thead>
          <tbody>
            {runs.map((r) => {
              const s = (r.stats ?? {}) as Record<string, number>;
              return (
                <tr key={r.id} className="border-t border-white/5">
                  <td className="py-1">{r.providerKey}</td>
                  <td>{timeAgo(r.startedAt)}</td>
                  <td><Badge tone={statusTone(r.status)}>{r.status}</Badge></td>
                  <td className="text-slate-400">{r.error ? r.error.slice(0, 120) : `seen ${s.seen ?? 0}, new ${s.created ?? 0}, upd ${s.updated ?? 0}, failed ${s.failed ?? 0}, mirrored ${s.mirrored ?? 0}`}</td>
                </tr>
              );
            })}
            {runs.length === 0 && <tr><td colSpan={4} className="py-3 text-slate-500">No runs yet.</td></tr>}
          </tbody>
        </table>
      </div>
    </div>
  );
}
