  assert.ok(v.sha1 && v.sha512 && v.fileBytes! > 0);
  assert.ok(v.gameVersions.length > 0);
  if (m.versions!.length > 1) assert.ok(m.versions![0].publishedAt! >= m.versions![1].publishedAt!);
});

