  assert.equal(m.source, "hangar");
  assert.equal(m.sourceId, "ViaVersion/ViaBackwards");
  assert.equal(m.license, "GPL");
  assert.ok(isRedistributable(m.license));
  assert.equal(m.appliesToVariant, "paper");
  assert.ok(m.gameVersions!.includes("1.21") || m.gameVersions!.length > 10);
  const v = m.versions![0];
  assert.equal(v.channel, "snapshot");
  assert.match(v.sha256!, /^[a-f0-9]{64}$/);
  const ext = parseHangarVersion({ ...vers.result[0], downloads: { PAPER: { externalUrl: "https://example.com/x.jar", downloadUrl: null, fileInfo: null } } });
  assert.equal(ext.fileUrl, null);
});

test("factorio: login-gated downloads are never given a fileUrl", () => {
  const list = fx("factorio-list.json") as { results: FzMod[] };
  const m = parseFactorioMod(list.results[0]);
  assert.equal(m.gameFamily, "factorio");
  assert.equal(m.source, "factorio_portal");
  assert.ok(m.versions![0].fileUrl === null);
  assert.ok(m.url!.startsWith("https://mods.factorio.com/mod/"));
});

test("ficsit: GraphQL row normalises with release/beta/alpha channels", () => {
  const body = fx("ficsit-list.json") as { data: { getMods: { mods: FsMod[] } } };
  const m = parseFicsitMod(body.data.getMods.mods[0]);
  assert.equal(m.gameFamily, "satisfactory");
  assert.equal(m.source, "ficsit");
  assert.ok(m.sourceId.length > 0);
  assert.ok(m.versions!.some((v) => v.channel === "release"));
  assert.equal(m.versions![0].fileUrl, null);
});

test("license policy: only open SPDX ids are redistributable; unknown is not", () => {
  for (const ok of ["MIT", "Apache-2.0", "GPL-3.0-only", "LGPL-3.0-or-later", "CC0-1.0", "GPL", "MPL-2.0"]) assert.ok(isRedistributable(ok), ok);
  for (const no of ["", null, undefined, "LicenseRef-All-Rights-Reserved", "All Rights Reserved", "Other", "Custom", "LicenseRef-Custom", "CC-BY-NC-4.0", "proprietary"]) assert.ok(!isRedistributable(no as string), String(no));
});

test("http: backoff grows, honours Retry-After, retries 429/5xx, 304 passthrough, pacing", async () => {
  assert.ok(HttpClient.backoffMs(0, null, () => 0) === 1000);
  assert.ok(HttpClient.backoffMs(3, null, () => 0) === 8000);
  assert.ok(HttpClient.backoffMs(20, null, () => 0) === 60000);
  assert.equal(HttpClient.backoffMs(0, "7"), 7250);

  const sleeps: number[] = [];
  let calls = 0;
  const seen: Record<string, string>[] = [];
  const c = new HttpClient({
    ratePerMin: 60,
    sleep: async (ms) => { sleeps.push(ms); },
    now: () => 0,
    fetchImpl: (async (_u: string, init: RequestInit) => {
      seen.push(init.headers as Record<string, string>);
      calls++;
      if (calls === 1) return new Response("", { status: 429, headers: { "retry-after": "2" } });
      if (calls === 2) return new Response("", { status: 503 });
      if (calls === 3) return new Response("{}", { status: 200, headers: { etag: '"abc"' } });
      return new Response(null, { status: 304 });
    }) as unknown as typeof fetch,
  });
  const ok = await c.jsonConditional<object>("https://x.test/a", { etag: '"old"' });
  assert.deepEqual(ok?.data, {});
  assert.equal(ok?.etag, '"abc"');
  assert.equal(c.retries, 2);
  assert.ok(sleeps.includes(2250), "Retry-After honoured");
  assert.match(seen[0]["User-Agent"], /Nxeon/);
  assert.equal(seen[0]["If-None-Match"], '"old"');
  assert.equal(await c.jsonConditional("https://x.test/a", { etag: '"abc"' }), null);
});

test("http: gives up after maxRetries with HttpError", async () => {
  const c = new HttpClient({ ratePerMin: 6000, maxRetries: 2, sleep: async () => {}, fetchImpl: (async () => new Response("", { status: 500 })) as unknown as typeof fetch });
  await assert.rejects(() => c.json("https://x.test/b"), (e: unknown) => e instanceof HttpError && e.status === 500);
});

test("mirror: content-addressed paths, traversal-proof", () => {
  const h = "a".repeat(64);
  assert.equal(blobRel(h), `files/aa/${h}`);
  assert.throws(() => blobRel("../../etc/passwd"));
  assert.throws(() => blobAbs("../outside"));
  assert.ok(KEY_RE.test(h) && !KEY_RE.test("../x") && !KEY_RE.test("A".repeat(64)));
});

test("slugify is stable and shell/URL inert", () => {
  assert.equal(slugify("Essentials X!!"), "essentials-x");
  assert.equal(slugify("../../x"), "x");
  assert.equal(slugify("***"), "mod");
});
