import { assertDbTarget } from "./db-target-guard";
assertDbTarget("modsync-mirror-selftest.ts");
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import fs from "node:fs";
import http from "node:http";
import { db } from "../lib/db";
import { HttpClient } from "../lib/modsync/http";
import { blobAbs, mirrorUsage, mirrorVersion, resolveLocal, verifyMirror } from "../lib/modsync/mirror";

const blobs: Record<string, Buffer> = {};
for (const n of ["a", "b", "c", "dup"]) blobs[`/${n}.jar`] = Buffer.alloc(1000, n === "dup" ? "a" : n);
blobs["/big.jar"] = Buffer.alloc(900, "z");

async function main() {
  const srv = http.createServer((req, res) => {
    const b = blobs[req.url ?? ""];
